// Code, the chain, Spec, and Ask are tabs side by side, each its own
// bar so that selecting the chain can show Code and Spec selected
// along with it, as one locked tab. The chain shows an icon: broken
// and dimmed until selected, then joined.
let selected = self.selected_tab;
let unified = selected == BOTH_TAB;
// The tint slides between the tabs, so going from Code to Spec passes
// through purple. Its position is the selected tab's index: 0 for
// Code, 1 for the chain, 2 for Spec, 3 for Ask.
let tint_slide = SpringAnimation::new(CHAIN_SPRING).to(selected as f32);
let (red, blue, green) = (cx.theme().red, cx.theme().blue, cx.theme().green);
let tint = move |position| tint(red, blue, green, position);
let chain_icon = if unified {
    IconName::Link
} else {
    IconName::Unlink
};
// A tab's contents: its label, or the chain's icon. The chain's icon
// is nudged toward Code or Spec while the other is selected alone: a
// selected tab shows its edge, but an unselected one only its label,
// set in from the edge, and the nudge splits that inset so the icon
// looks as far from one as from the other.
let tab = |ix: usize| match TABS[ix] {
    SendMode::Both => Tab::new().child(
        div()
            .relative()
            .flex()
            .child(gpui_kit::TestSupportExt::test_support(
                div()
                    .id("both-icon")
                    .flex()
                    .opacity(if unified { 1. } else { 0.5 })
                    .child(Icon::new(chain_icon).size_4()),
            ))
            .with_spring("chain-nudge", tint_slide.clone(), |this, position| {
                let toward_spec = tab_tint_shown(0, position) - tab_tint_shown(2, position);
                this.left(TAB_LABEL_INSET * 0.5 * toward_spec)
            }),
    ),
    mode => Tab::new().label(mode.label()),
};
// A tint laid over a tab, as wide as the tab itself (an invisible copy
// of it) rather than its bar, fading out as the tab is deselected.
let tab_tint = |ix: usize| {
    let tint_slide = tint_slide.clone();
    let copy = match TABS[ix] {
        SendMode::Both => Tab::new().child(div().size_4()),
        mode => Tab::new().label(mode.label()),
    };
    div()
        .absolute()
        .top_0()
        .bottom_0()
        .left_0()
        .flex()
        .child(
            TabBar::new(("tint-width", ix))
                .selected_index(0)
                .child(copy)
                .invisible(),
        )
        .with_spring(("tab-tint", ix), tint_slide, move |this, position| {
            let shown = tab_tint_shown(ix, position);
            let color = tint(position);
            this.bg(Hsla {
                a: color.a * shown,
                ..color
            })
        })
};
let chat_input = cx.entity().downgrade();
let full_tab = |ix: usize| {
    let chat_input = chat_input.clone();
    let bar = TabBar::new(TABS[ix].id())
        .on_click(move |_, window, cx| {
            chat_input
                .update(cx, |this, cx| this.select_tab(ix, window, cx))
                .ok();
        })
        .child(tab(ix));
    if selected == ix || (unified && ix != ASK_TAB) {
        bar.selected_index(0)
    } else {
        bar
    }
};
// While the three read as one tab, the facing borders where one meets
// the next are covered, in their purple.
let seam_cover = cx.theme().tab_active.blend(tint(BOTH_TAB as f32));
let seam = || {
    div()
        .absolute()
        .top_0()
        .bottom_0()
        .left(px(-1.))
        .w(px(2.))
        .when(unified, |this| this.bg(seam_cover))
};
let code = div().relative().child(full_tab(0)).child(tab_tint(0));
let both = div()
    .id("both-tooltip")
    .relative()
    .tooltip(|window, cx| Tooltip::new(SendMode::Both.label()).build(window, cx))
    .child(full_tab(BOTH_TAB))
    .child(tab_tint(BOTH_TAB))
    .child(seam());
let spec = div()
    .relative()
    .child(full_tab(2))
    .child(tab_tint(2))
    .child(seam());
// Ask stretches to the right edge.
let ask = div()
    .relative()
    .flex_1()
    .child(full_tab(ASK_TAB).w_full())
    .child(tab_tint(ASK_TAB));
let tabs = gpui_kit::TestSupportExt::test_support(
    div()
        .id("chat-tabs")
        .relative()
        .flex()
        .items_center()
        .bg(cx.theme().tab_bar)
        .child(
