420	/// Rounds `length` up to a whole device pixel. Layout rounds lengths to
421	/// device pixels half toward zero, so at fractional scales an input sized in
422	/// logical pixels can come out a fraction of a pixel short of its rows; the
423	/// editor then takes its last row for out of view and scrolls it in for a
424	/// frame, which flickers the text a line up and back.
425	fn ceil_to_device_pixel(length: Pixels, window: &Window) -> Pixels {
426	    let scale_factor = window.scale_factor();
427	    // Float noise just past a whole device pixel must not round up to the next.
428	    px((f32::from(length) * scale_factor - 1e-3).ceil() / scale_factor)
429	}
