                    .id("tabs")
                    .flex_1()
                    .mx(-padding_x)
                    .px(padding_x)
                    .overflow_x_hidden()
                    .child(
                        h_flex()
                            .id("tabs-inner")
                            .mx(-padding_x)
                            .px(padding_x)
                            .relative()
                            .gap(gap)
