    type Bounds = gpui_kit::Bounds<gpui_kit::Pixels>;

    /// The Code, chain, Spec, and Ask tabs, then the chain's icon, as last
    /// laid out.
    fn tab_layout(window: &mut Window, cx: &mut gpui_kit::App) -> [Bounds; 5] {
        window.render_frame(cx);
        [
            window.within("code-tab").find(0usize).bounds(),
            window.within("both-tab").find(0usize).bounds(),
            window.within("spec-tab").find(0usize).bounds(),
            window.within("ask-tab").find(0usize).bounds(),
            window.find("both-icon").bounds(),
        ]
    }

    /// Draws frames until the chain's icon is as far from what shows of Code
    /// as from what shows of Spec: a selected tab's edge, or an unselected
    /// tab's label.
    fn settle_icon(
        handle: gpui_kit::AnyWindowHandle,
        code_selected: bool,
        spec_selected: bool,
        cx: &mut TestAppContext,
    ) -> [Bounds; 5] {
        let inset = |selected: bool| {
            if selected {
                super::px(0.)
            } else {
                super::TAB_LABEL_INSET
            }
        };
        let start = std::time::Instant::now();
        loop {
            let layout = cx
                .update_window(handle, |_, window, cx| tab_layout(window, cx))
                .unwrap();
            let [code, _, spec, _, icon] = layout;
            let before = icon.left() - (code.right() - inset(code_selected));
            let after = spec.left() + inset(spec_selected) - icon.right();
            if (before - after).abs() <= super::px(0.5) {
                return layout;
            }
            assert!(
                start.elapsed() < TIMEOUT,
                "the chain's icon did not settle evenly spaced: {before:?} before, {after:?} after"
            );
            std::thread::sleep(Duration::from_millis(16));
        }
    }

    /// The chain is a tab like the others, with no gap either side of it, and
    /// its icon looks evenly spaced between Code and Spec whichever is
    /// selected.
    #[gpui_kit::test]
    async fn chain_is_an_evenly_spaced_tab(cx: &mut TestAppContext) {
        cx.update(|cx| {
