        cx.update_window(handle, |_, window, cx| {
            window.render_frame(cx);
            let viewport = window.viewport_size();
            let menu = window.find("completion-menu").bounds();
            assert!(
                menu.size.height > gpui_kit::px(0.)
                    && menu.top() >= gpui_kit::px(0.)
