        })
        .await;

        // Code starts selected.
        let [code, chain, spec, ask, _] = settle_icon(handle, true, false, cx);
        for (left, right, between) in [
            (code, chain, "Code and the chain"),
            (chain, spec, "the chain and Spec"),
            (spec, ask, "Spec and Ask"),
        ] {
            assert!(
                (right.left() - left.right()).abs() <= super::px(0.5),
                "there is a gap between {between}: {left:?}, {right:?}"
            );
            assert_eq!(left.size.height, right.size.height, "{between}");
        }

        // Tab moves to the chain, which selects Code and Spec with it.
        cx.update_window(handle, |_, window, cx| window.press("tab", cx))
            .unwrap();
        let layout = settle_icon(handle, true, true, cx);
        cx.update_window(handle, |_, window, cx| {
            use gpui_kit::component::ActiveTheme as _;
            let theme = cx.theme();
            let tint = super::tint(theme.red, theme.blue, theme.green, super::BOTH_TAB as f32);
            eprintln!(
                "DEBUG-TEMP tabs {layout:?}\nseam-both {:?}\nseam-spec {:?}\ntab_active {:?} tab_bar {:?} border {:?} tint {:?} seam_cover {:?}",
                window.find("seam-both").bounds(),
                window.find("seam-spec").bounds(),
                theme.tab_active,
                theme.tab_bar,
                theme.border,
